"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { MagnifyingGlassIcon, XIcon, SpinnerGapIcon } from "@phosphor-icons/react";

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(" ");

interface SearchInputProps {
  value: string;
  onChange: (value: string) => void;
  /** Called after debounceMs of no typing. */
  onSearch?: (value: string) => void;
  debounceMs?: number;
  loading?: boolean;
  placeholder?: string;
  /** A single key (e.g. "/") that focuses the field from anywhere on the page. */
  shortcut?: string;
  /** Renders a "N results" pill on the right when set and the field is non-empty. */
  resultCount?: number;
  ariaLabel?: string;
}

export function SearchInput({
  value,
  onChange,
  onSearch,
  debounceMs = 300,
  loading = false,
  placeholder = "Search",
  shortcut,
  resultCount,
  ariaLabel = "Search",
}: SearchInputProps) {
  const reduce = useReducedMotion();
  const inputRef = useRef<HTMLInputElement>(null);
  const [focused, setFocused] = useState(false);

  const onSearchRef = useRef(onSearch);
  useEffect(() => {
    onSearchRef.current = onSearch;
  }, [onSearch]);

  useEffect(() => {
    if (!onSearchRef.current) return;
    const id = setTimeout(() => onSearchRef.current?.(value), debounceMs);
    return () => clearTimeout(id);
  }, [value, debounceMs]);

  useEffect(() => {
    if (!shortcut) return;
    const onKey = (e: KeyboardEvent) => {
      const el = document.activeElement;
      const typing =
        el instanceof HTMLInputElement ||
        el instanceof HTMLTextAreaElement ||
        (el instanceof HTMLElement && el.isContentEditable);
      if (e.key === shortcut && !typing) {
        e.preventDefault();
        inputRef.current?.focus();
      }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [shortcut]);

  const showClear = value.length > 0;
  const showHint = !!shortcut && !focused && value.length === 0;

  return (
    <div
      className={cx(
        "flex h-10 w-full items-center gap-2 rounded-md border bg-stone-100 px-2.5 text-sm transition-[border-color,box-shadow] duration-150 dark:bg-stone-950",
        focused
          ? "border-emerald-600 ring-2 ring-emerald-600/25 dark:border-emerald-400 dark:ring-emerald-400/25"
          : "border-stone-300 dark:border-stone-700",
      )}
    >
      <span className="relative h-4 w-4 shrink-0 text-stone-500">
        <AnimatePresence mode="wait" initial={false}>
          {loading ? (
            <motion.span
              key="spin"
              initial={reduce ? {} : { opacity: 0, rotate: -90 }}
              animate={reduce ? {} : { opacity: 1, rotate: 0 }}
              exit={reduce ? {} : { opacity: 0 }}
              className="absolute inset-0 text-emerald-700 dark:text-emerald-400"
            >
              <motion.span
                className="block"
                animate={reduce ? {} : { rotate: 360 }}
                transition={{ duration: 0.8, repeat: Infinity, ease: "linear" }}
              >
                <SpinnerGapIcon size={16} weight="bold" aria-hidden />
              </motion.span>
            </motion.span>
          ) : (
            <motion.span
              key="glass"
              initial={reduce ? {} : { opacity: 0, scale: 0.8 }}
              animate={reduce ? {} : { opacity: 1, scale: 1 }}
              exit={reduce ? {} : { opacity: 0 }}
              className="absolute inset-0"
            >
              <MagnifyingGlassIcon size={16} aria-hidden />
            </motion.span>
          )}
        </AnimatePresence>
      </span>

      <input
        ref={inputRef}
        type="search"
        aria-label={ariaLabel}
        value={value}
        placeholder={placeholder}
        onChange={(e) => onChange(e.target.value)}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        onKeyDown={(e) => {
          if (e.key !== "Escape") return;
          // First Escape clears the field and is consumed here, so a parent
          // results panel stays open. On an empty field it bubbles instead,
          // letting the parent close.
          if (value) {
            e.stopPropagation();
            onChange("");
          }
        }}
        style={{ outline: "none" }}
        className="min-w-0 flex-1 bg-transparent py-1 text-stone-900 placeholder:text-stone-400 [&::-webkit-search-cancel-button]:hidden dark:text-stone-100"
      />

      <AnimatePresence initial={false} mode="popLayout">
        {resultCount != null && value.length > 0 && !loading && (
          <motion.span
            key="count"
            initial={reduce ? { opacity: 0 } : { opacity: 0, y: 4 }}
            animate={{ opacity: 1, y: 0 }}
            exit={reduce ? { opacity: 0 } : { opacity: 0, y: -4 }}
            className="shrink-0 rounded-full bg-stone-100 px-1.5 py-0.5 text-[11px] font-medium tabular-nums text-stone-500 dark:bg-stone-800 dark:text-stone-400"
          >
            {resultCount} {resultCount === 1 ? "result" : "results"}
          </motion.span>
        )}
      </AnimatePresence>

      {showHint && (
        <kbd className="pointer-events-none hidden shrink-0 rounded border border-stone-200 bg-stone-50 px-1.5 py-0.5 font-mono text-[11px] font-medium text-stone-500 sm:block dark:border-stone-700 dark:bg-stone-900 dark:text-stone-500">
          {shortcut}
        </kbd>
      )}

      <AnimatePresence initial={false}>
        {showClear && (
          <motion.button
            key="clear"
            type="button"
            aria-label="Clear search"
            onClick={() => {
              onChange("");
              inputRef.current?.focus();
            }}
            initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
            transition={{ type: "spring", stiffness: 520, damping: 30 }}
            className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-stone-500 transition-colors hover:bg-stone-100 hover:text-stone-700 dark:hover:bg-white/10 dark:hover:text-stone-100"
          >
            <XIcon size={12} weight="bold" aria-hidden />
          </motion.button>
        )}
      </AnimatePresence>
    </div>
  );
}

/*
Usage:

const [q, setQ] = useState("");

<SearchInput
  value={q}
  onChange={setQ}
  onSearch={(v) => runQuery(v)}   // debounced
  loading={isFetching}
  shortcut="/"
  resultCount={q ? results.length : undefined}
  placeholder="Search commands"
/>
*/
